#!/usr/bin/env python3
"""
Blind re-derivation for TASK-20260913-25da8c (validator, Phase 1).

Written from scratch in this session, BEFORE opening the producer's
rederive.py.  Everything below is an exact evaluation of formulas read
directly from inputs/SEMAEV-2015-310/paper_fulltext.md (eq. 11, 15, 16, 17,
Section 4.5.2) and from the cost model STATED in IDEA-20260913-191ed2 (C3)
and IDEA-20260913-8138a0 (C5).  Nothing is measured; no degree is asserted.

Sources of the formulas (read by this validator, not quoted from the correction):

  eq. (11):  P(q,m,t,|V|) = 1 - (1 - 1/q)^K,  K ~ |V|^t / t!,
             ~ 1 - exp(-|V|^t/(q t!)),  and if |V|^t/(q t!) = o(1) then
             P ~ |V|^t / (q t!).       [paper_fulltext.md lines 400-427]
  Sec 4.5.2: P(n,m,m,k) ~ 2^{mk-n}/m!  with k = ceil(n/m)   [lines 1064-1067]
  eq. (15):  stage1 = 2^k n^{4w} / P(n,m,m,k) ~ (m!/2^{mk-n}) 2^k n^{4w};
             "for w = 3 that is AT MOST m! 2^{n/m} n^12"  [lines 1074-1091]
  eq. (16):  stage2 = 2^{k w'}, w' = 2                     [lines 1093-1101]
  Table 3:   columns 2^{n/2}, m, m! 2^{n/m} n^12, 2^{2n/m} (un-ceiled k)
  IDEA-191ed2 (C3): stage1 = 2^k ( (1/P) C(d_unsat) + C(d_sat) ), C(d) = n^{d w}
  IDEA-8138a0 (C5): d(n,m) >= [c - 1/c'] sqrt(n ln n) / (w log2(n(m-1))),
             c' = sqrt(2 ln 2), c = 2/c'.

Charges compared (integer k = ceil(n/m) throughout unless stated):
  A  "m!-only":            1/P = m!
  B  "eq.(11) linearised": 1/P = m! 2^{n-mk}
  B* "eq.(11) unlinearised": P = 1 - exp(-lambda), lambda = 2^{mk-n}/m!
"""
import json, math, statistics, hashlib, sys, datetime

LN2 = math.log(2.0)

def log2_fact(m):
    return math.log2(math.factorial(m))

def ceil_k(n, m):
    return -(-n // m)

def logaddexp2(a, b):
    if a == -math.inf: return b
    if b == -math.inf: return a
    hi, lo = max(a, b), min(a, b)
    return hi + math.log2(1.0 + 2.0 ** (lo - hi))

def log2_inv_P(n, m, k, charge):
    """log2 of 1/P under the named charge."""
    if charge == "A":
        return log2_fact(m)
    if charge == "B":
        return log2_fact(m) + (n - m * k)
    if charge == "Bstar":
        lam_log2 = (m * k - n) - log2_fact(m)      # log2(lambda)
        if lam_log2 < -50:
            # 1 - e^{-lam} = lam (1 - lam/2 + ...); the correction is below double
            # precision here and 2**lam_log2 may underflow, so use the linear value.
            return -lam_log2
        lam = 2.0 ** lam_log2
        P = -math.expm1(-lam)                        # 1 - e^{-lambda}, exact in double
        return -math.log2(P)
    raise ValueError(charge)

def log2_stage1(n, m, k, d_sat, charge, omega=3.0, d_unsat=4):
    L = math.log2(n)
    unsat = log2_inv_P(n, m, k, charge) + d_unsat * omega * L
    sat = d_sat * omega * L
    return k + logaddexp2(unsat, sat)

def log2_stage2(k, omega_p=2.0):
    return k * omega_p

def log2_total(n, m, d_sat, charge, omega=3.0, omega_p=2.0, d_unsat=4):
    k = ceil_k(n, m)
    return logaddexp2(log2_stage1(n, m, k, d_sat, charge, omega, d_unsat),
                      log2_stage2(k, omega_p))

def optimise(n, d_sat, charge, omega=3.0, omega_p=2.0, d_unsat=4, m_lo=2, m_hi=None):
    if m_hi is None: m_hi = n
    best = None
    for m in range(m_lo, m_hi + 1):
        t = log2_total(n, m, d_sat, charge, omega, omega_p, d_unsat)
        if best is None or t < best[0] - 1e-12:
            best = (t, m, ceil_k(n, m))
    return best  # (log2_total, m, k)

def r(x, nd=4):
    return None if x is None else round(x, nd)

out = {
    "schema": "validator.blind_rederivation.independent_figures.v1",
    "task_id": "TASK-20260913-25da8c",
    "phase": 1,
    "written_at_utc": datetime.datetime.now(datetime.timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ"),
    "derived_from": [
        "inputs/SEMAEV-2015-310/paper_fulltext.md (eq. 11 lines 400-427; Sec 4.5.2 lines 1062-1091; eq. 16 lines 1093-1101; Table 3 lines 1157-1234)",
        "inputs/SEMAEV-2015-310/tables.yaml (table_3 rows)",
        "ledger/proposals/IDEA-20260913-191ed2.yaml (C3 two-term charge statement)",
        "ledger/proposals/IDEA-20260913-8138a0.yaml (C5 inequality statement, lines 89-96)",
        "ledger/corrections/CORR-20260913-53739b.yaml (statements of which cells / parameters only)",
    ],
    "not_read_before_this_file": [
        "coordination/goals/GOAL-SEMBIN-5078bc/batches/BATCH-9d649f/coordinator-rederivation-53739b/ (blind_from; not opened, listed, grepped or imported)"
    ],
    "parameters": {"omega": 3, "omega_prime": 2, "d_unsat": 4, "k": "ceil(n/m)", "C(d)": "n^(d*omega)",
                   "total": "stage1 + stage2 = 2^k((1/P) n^(4w) + n^(d_sat w)) + 2^(k w')",
                   "m_range_for_optimisation": "[2, n]"},
    "charges": {"A": "1/P = m!", "B": "1/P = m! 2^(n-mk)  [eq. (11) linearised at |V|=2^k, q=2^n, t=m]",
                "Bstar": "P = 1 - exp(-2^(mk-n)/m!)  [eq. (11) unlinearised]"},
}

# ---------------------------------------------------------------- 0. eq.(11) reading
n0, m0, k0 = 571, 12, 48
out["eq11_reading"] = {
    "statement": "P(n,m,m,k) = 2^(mk-n)/m!  =>  1/P = m! 2^(n-mk); equals m! iff mk = n",
    "at_571_12_48": {
        "mk_minus_n": m0 * k0 - n0,
        "log2_m_factorial": r(log2_fact(m0)),
        "log2_inv_P_A": r(log2_inv_P(n0, m0, k0, "A")),
        "log2_inv_P_B": r(log2_inv_P(n0, m0, k0, "B")),
        "log2_inv_P_Bstar": r(log2_inv_P(n0, m0, k0, "Bstar"), 8),
        "lambda_log2": r((m0 * k0 - n0) - log2_fact(m0)),
        "P_B_leq_1_check": (m0 * k0 - n0) - log2_fact(m0) <= 0,
    },
    "P_leq_1_always_under_ceil_k": "slack mk-n in [0,m-1] and m! >= 2^(m-1) for m>=1, so lambda <= 1; equality only at m=2, slack 1",
}

# ---------------------------------------------------------------- 1. stage-1 at (571,12,48)
cells = {}
for ch in ("A", "B", "Bstar"):
    cells[ch] = {str(d): r(log2_stage1(n0, m0, k0, d, ch)) for d in (4, 5, 6, 7)}
out["stage1_at_571_12_48_bits"] = cells

# ---------------------------------------------------------------- 2. re-optimised totals at n=571
reopt = {}
for ch in ("A", "B", "Bstar"):
    reopt[ch] = {}
    for d in (4, 5, 6, 7):
        t, m, k = optimise(n0, d, ch)
        reopt[ch][str(d)] = {"log2_total": r(t), "m": m, "k": k}
out["reoptimised_totals_at_571"] = reopt
out["memory_k_shift_d_sat_6"] = {
    "A": {"k_at_paper_optimum": 48, "k_reopt": reopt["A"]["6"]["k"], "saving_bits": 48 - reopt["A"]["6"]["k"]},
    "B": {"k_at_paper_optimum": 48, "k_reopt": reopt["B"]["6"]["k"], "saving_bits": 48 - reopt["B"]["6"]["k"]},
}
out["rho_at_571_bits"] = 571 / 2

# ---------------------------------------------------------------- 3. crossovers with 2^{n/2}
N_LO, N_HI = 100, 1000
def beats_rho(n, d, ch):
    return optimise(n, d, ch)[0] < n / 2.0

cross = {}
for ch in ("A", "B"):
    cross[ch] = {}
    for d in (4, 5, 6, 7):
        wins = [n for n in range(N_LO, N_HI + 1) if beats_rho(n, d, ch)]
        first = wins[0] if wins else None
        losses_after_first = [n for n in range(first, N_HI + 1) if n not in set(wins)] if first else None
        cross[ch][str(d)] = {"first_n_beating_rho": first,
                             "monotone_after_first": (losses_after_first == []) if first else None,
                             "n_values_not_beating_rho_after_first": losses_after_first}
out["crossover_with_2_pow_n_half"] = cross

# the disagreement set at d_sat = 4
dis = [n for n in range(N_LO, N_HI + 1) if beats_rho(n, 4, "B") != beats_rho(n, 4, "A")]
out["charge_disagreement_set_d_sat_4"] = {
    "n_values": dis, "count": len(dis),
    "min": min(dis) if dis else None, "max": max(dis) if dis else None,
    "integers_in_[min,max]": (max(dis) - min(dis) + 1) if dis else None,
    "B_beats_rho_and_A_does_not_count": sum(1 for n in dis if beats_rho(n, 4, "B") and not beats_rho(n, 4, "A")),
}

# ---------------------------------------------------------------- 4. overcharge statistics, n in [100,1000], d_sat = 4
over = []
mdiff = 0
per_n = {}
for n in range(N_LO, N_HI + 1):
    tA, mA, kA = optimise(n, 4, "A")
    tB, mB, kB = optimise(n, 4, "B")
    over.append(tA - tB)
    if mA != mB: mdiff += 1
    per_n[n] = (tA, mA, kA, tB, mB, kB)
out["overcharge_A_minus_B_bits_d_sat_4_n_100_1000"] = {
    "mean": r(statistics.mean(over)), "median": r(statistics.median(over)),
    "min": r(min(over)), "max": r(max(over)), "sd_sample": r(statistics.stdev(over)),
    "sd_population": r(statistics.pstdev(over)),
    "count_n": len(over), "count_n_where_argmin_m_differs": mdiff,
    "argmin_n_of_min": N_LO + over.index(min(over)), "argmin_n_of_max": N_LO + over.index(max(over)),
    "at_571": {"A": {"log2_total": r(per_n[571][0]), "m": per_n[571][1], "k": per_n[571][2]},
               "B": {"log2_total": r(per_n[571][3]), "m": per_n[571][4], "k": per_n[571][5]}},
    "at_310": {"A": {"log2_total": r(per_n[310][0]), "m": per_n[310][1], "k": per_n[310][2]},
               "B": {"log2_total": r(per_n[310][3]), "m": per_n[310][4], "k": per_n[310][5]}},
    "bound_check_max_leq_m_minus_1": all(
        (per_n[n][0] - per_n[n][3]) <= max(per_n[n][1], per_n[n][4]) - 1 + 1e-9 for n in per_n),
}

# ---------------------------------------------------------------- 5. linearisation control at the B optimum (d_sat = 4)
lam_max, lam_argn, lam_1000, maxdiff, maxdiff_n = -math.inf, None, None, 0.0, None
lam_at_163 = None
n_lambda_above_minus_10_47 = []
n_where_Bstar_argmin_differs = []
n_where_diff_gt_0_001 = 0
for n in range(N_LO, N_HI + 1):
    tB, mB, kB = optimise(n, 4, "B")
    lam_log2 = (mB * kB - n) - log2_fact(mB)
    if lam_log2 > lam_max: lam_max, lam_argn = lam_log2, n
    if n == 1000: lam_1000 = lam_log2
    if n == 163: lam_at_163 = (lam_log2, mB, kB)
    if lam_log2 > -10.47 + 1e-9: n_lambda_above_minus_10_47.append(n)
    tBs, mBs, kBs = optimise(n, 4, "Bstar")
    if abs(tBs - tB) > maxdiff: maxdiff, maxdiff_n = abs(tBs - tB), n
    if abs(tBs - tB) > 0.001: n_where_diff_gt_0_001 += 1
    if mBs != mB: n_where_Bstar_argmin_differs.append(n)
cross_Bstar = {str(d): next((n for n in range(N_LO, N_HI + 1) if optimise(n, d, "Bstar")[0] < n / 2.0), None)
               for d in (4, 5, 6, 7)}
out["linearisation_control"] = {
    "max_log2_lambda_at_B_optimum": r(lam_max), "n_at_max": lam_argn,
    "B_optimum_at_n_max": {"m": optimise(lam_argn, 4, "B")[1], "k": optimise(lam_argn, 4, "B")[2]},
    "log2_lambda_at_n_163": {"log2_lambda": r(lam_at_163[0]), "m": lam_at_163[1], "k": lam_at_163[2]},
    "log2_lambda_at_n_1000": r(lam_1000),
    "count_n_with_log2_lambda_above_minus_10_47": len(n_lambda_above_minus_10_47),
    "first_20_such_n": n_lambda_above_minus_10_47[:20],
    "max_abs_bits_Bstar_minus_B_over_range": r(maxdiff, 6), "n_at_max_diff": maxdiff_n,
    "count_n_with_abs_diff_gt_0_001_bits": n_where_diff_gt_0_001,
    "n_where_Bstar_argmin_m_differs_from_B": n_where_Bstar_argmin_differs,
    "crossover_first_n_under_Bstar": cross_Bstar,
    "note": "lambda = 2^(mk-n)/m! evaluated at the d_sat=4 charge-B optimum; the linearisation P~lambda is accurate only when lambda is small",
}

# ---------------------------------------------------------------- 6. omega' invariance, charge A, d_sat = 6, n = 571
wp = {}
for op in (1.0, 2.0, 2.376, 3.0):
    t, m, k = optimise(571, 6, "A", omega_p=op)
    t21 = log2_total(571, 21, 6, "A", omega_p=op)
    wp[str(op)] = {"opt_log2_total": r(t), "m": m, "k": k, "m21_log2_total": r(t21), "m21_minus_opt": r(t21 - t)}
out["omega_prime_invariance_A_d6_571"] = wp

# ---------------------------------------------------------------- 7. un-ceiled k: A and B coincide
out["unceiled_k_coincidence"] = {}
for n in (283, 571):
    m = optimise(n, 4, "A")[1]
    k_real = n / m
    a = log2_fact(m); b = log2_fact(m) + (n - m * k_real)
    out["unceiled_k_coincidence"][str(n)] = {"m": m, "abs_diff_bits": abs(a - b)}

# ---------------------------------------------------------------- 8. Table 3 baseline (paper's own un-ceiled formula, omega=3)
table3 = [(100,6,7.49e31,1.08e10),(150,7,1.84e36,7.96e12),(200,8,5.54e39,1.12e15),(250,9,4.97e42,5.29e16),
          (300,10,2.07e45,1.15e18),(310,10,6.13e45,4.61e18),(350,10,4.21e47,1.18e21),(400,11,5.92e49,7.81e21),
          (409,11,1.36e50,2.43e22),(450,11,5.68e51,4.26e24),(500,12,4.08e53,1.21e25),(571,12,1.21e56,4.44e28)]
t3 = []
for n, m, s1, s2 in table3:
    mine1 = log2_fact(m) + n / m + 12 * math.log2(n)
    mine2 = 2 * n / m
    t3.append({"n": n, "m": m, "paper_log2_stage1": r(math.log2(s1), 3), "mine_log2_stage1": r(mine1, 3),
               "rel_err_stage1": r(2 ** (mine1 - math.log2(s1)) - 1, 4),
               "paper_log2_stage2": r(math.log2(s2), 3), "mine_log2_stage2": r(mine2, 3),
               "rel_err_stage2": r(2 ** (mine2 - math.log2(s2)) - 1, 4)})
def unceiled_opt(n):
    best = None
    for m in range(2, n + 1):
        t = log2_fact(m) + n / m + 12 * math.log2(n)
        if best is None or t < best[0]: best = (t, m)
    return best
first_unceiled = next(n for n in range(100, 1001) if unceiled_opt(n)[0] < n / 2)
out["table3_baseline_unceiled_k"] = {"rows": t3, "max_abs_rel_err": max(max(abs(x["rel_err_stage1"]), abs(x["rel_err_stage2"])) for x in t3),
                                     "first_n_where_min_m_stage1_lt_rho": first_unceiled,
                                     "paper_571_row_log2": r(math.log2(1.21e56), 2)}

# ---------------------------------------------------------------- 9. per-degree price and margin at n = 310 and 571 (IDEA-191ed2 sota_delta claim)
def price(n, ch):
    t4 = optimise(n, 4, ch)[0]; t5 = optimise(n, 5, ch)[0]; t6 = optimise(n, 6, ch)[0]
    return {"reopt_total_d4": r(t4), "reopt_total_d5": r(t5), "reopt_total_d6": r(t6),
            "one_degree_cost_bits_reopt": r(t5 - t4), "two_degree_cost_bits_reopt": r(t6 - t4),
            "margin_over_rho_bits_d4": r(n / 2 - t4),
            "margin_lt_one_degree_cost": (n / 2 - t4) < (t5 - t4)}
out["degree_price_and_margin"] = {
    "310": {"A": price(310, "A"), "B": price(310, "B")},
    "571": {"A": price(571, "A"), "B": price(571, "B")},
    "571_fixed_m12_k48_one_degree_bits": {"A": r(log2_stage1(571,12,48,5,"A") - log2_stage1(571,12,48,4,"A")),
                                          "B": r(log2_stage1(571,12,48,5,"B") - log2_stage1(571,12,48,4,"B"))},
    "571_fixed_m12_k48_two_degree_bits_d6_minus_d4": {"A": r(log2_stage1(571,12,48,6,"A") - log2_stage1(571,12,48,4,"A")),
                                                       "B": r(log2_stage1(571,12,48,6,"B") - log2_stage1(571,12,48,4,"B"))},
    "310_fixed_m10_k31_one_degree_bits": {"A": r(log2_stage1(310,10,31,5,"A") - log2_stage1(310,10,31,4,"A")),
                                          "B": r(log2_stage1(310,10,31,5,"B") - log2_stage1(310,10,31,4,"B")),
                                          "slack_mk_minus_n": 10 * 31 - 310},
    "310_fixed_m11_k29_B": {"d4": r(log2_stage1(310,11,29,4,"B")), "d5": r(log2_stage1(310,11,29,5,"B")),
                            "one_degree_bits": r(log2_stage1(310,11,29,5,"B") - log2_stage1(310,11,29,4,"B")),
                            "slack_mk_minus_n": 11 * 29 - 310},
    "571_12_48_dominant_term_at_d_sat_5": {
        "A": "unsat" if (log2_inv_P(571,12,48,"A") + 12*math.log2(571)) > 15*math.log2(571) else "sat",
        "B": "unsat" if (log2_inv_P(571,12,48,"B") + 12*math.log2(571)) > 15*math.log2(571) else "sat"},
    "arm_switch_threshold_d_sat_minus_d_unsat_at_571_12_48": {
        "A_omega3": r(log2_fact(12) / (3 * math.log2(571))),
        "B_omega3": r((log2_fact(12) + 571 - 12 * 48) / (3 * math.log2(571))),
        "A_omega2376": r(log2_fact(12) / (2.376 * math.log2(571))),
        "B_omega2376": r((log2_fact(12) + 571 - 12 * 48) / (2.376 * math.log2(571)))},
}

# ---------------------------------------------------------------- 10. correction_2: (C5) floor coefficient route dependence
cp = math.sqrt(2 * LN2); c = 2 / cp; bracket = c - 1 / cp
def floor_val(n, m, omega):
    return bracket * math.sqrt(n * math.log(n)) / (omega * math.log2(n * (m - 1)))
def coeff(n, m, omega):
    return floor_val(n, m, omega) / math.sqrt(n / math.log(n))
c2 = {"c_prime": r(cp, 6), "c": r(c, 6), "c_minus_1_over_c_prime": r(bracket, 6), "c_over_2": r(c / 2, 6),
      "collapse_m2_coefficient": {"omega3": r(c * LN2 / (2 * 3), 5), "omega2.376": r(c * LN2 / (2 * 2.376), 5)},
      "collapse_m_eq_n_coefficient": {"omega3": r(c * LN2 / (4 * 3), 5), "omega2.376": r(c * LN2 / (4 * 2.376), 5)}}
n = 571
m_route = n / math.log2(n)
c2["at_571"] = {
    "m_route_real": r(m_route, 3), "m_route_int": round(m_route),
    "omega3": {str(m): {"floor": r(floor_val(n, m, 3)), "coefficient": r(coeff(n, m, 3), 5)}
               for m in (2, 3, 12, round(m_route), 571)},
    "omega3_route_real_m": {"floor": r(floor_val(n, m_route, 3)), "coefficient": r(coeff(n, m_route, 3), 5)},
    "omega2.376": {str(m): {"floor": r(floor_val(n, m, 2.376)), "coefficient": r(coeff(n, m, 2.376), 5)}
                   for m in (2, 571)},
    "floor_interval_omega3_over_m_in_2_n": [r(min(floor_val(n, m, 3) for m in range(2, 572))),
                                             r(max(floor_val(n, m, 3) for m in range(2, 572)))],
    "assumption1_dF4": 4,
}
c2["route_coefficient_vs_n_omega3"] = {}
for nn in (571, 1e4, 1e6, 1e10, 1e20):
    mr = nn / math.log2(nn)
    c2["route_coefficient_vs_n_omega3"][f"{nn:g}"] = {"real_m": r(coeff(nn, mr, 3), 5), "rounded_m": r(coeff(nn, round(mr), 3), 5)}
# n at which the floor first reaches d = 4 (the "n ~ 3400 crossing" in EXP-SEMBIN-92724f approval_basis), per route
def first_n_floor_ge(target, route, omega):
    n = 100
    while n < 10**8:
        m = {"m2": 2, "route": max(2, round(n / math.log2(n))), "m_eq_n": n}[route]
        if floor_val(n, m, omega) >= target: return n
        n += 1
    return None
c2["first_n_floor_reaches_4_omega3"] = {rt: first_n_floor_ge(4, rt, 3) for rt in ("m2", "route", "m_eq_n")}
c2["first_n_floor_reaches_4_omega2.376"] = {rt: first_n_floor_ge(4, rt, 2.376) for rt in ("m2", "route", "m_eq_n")}
c2["coefficient_limit_ratio_check"] = {"log2(n(m-1))/log2(n) at route, n=571": r(math.log2(n * (round(m_route) - 1)) / math.log2(n), 5)}
out["correction_2_floor"] = c2

# ---------------------------------------------------------------- self-hash of the derivation source
with open(__file__, "rb") as f:
    src = f.read()
out["derivation_source_sha256"] = hashlib.sha256(src).hexdigest()
out["derivation_source"] = src.decode()

json.dump(out, sys.stdout, indent=1)
